node -e 'const fs=require("fs");const S="scripts/check-cache-budget.mjs";if(!fs.existsSync(S))process.exit(79)
const src=fs.readFileSync(S,"utf8");const bad=[]
const code=src.split("\n").filter(l=>!/^\s*(\/\/|\*)/.test(l)).join("\n")
const calls=[];for(let i=code.indexOf("rmSync(");i>=0;i=code.indexOf("rmSync(",i+1)){const e=code.indexOf(")",i);calls.push([i,code.slice(i,e<0?i+120:e)])}
if(calls.length===0)process.exit(79)
const intoCache=calls.filter(c=>/cacheDir|\.next\/cache/.test(c[1]));const elsewhere=calls.filter(c=>!/cacheDir|\.next\/cache/.test(c[1]))
if(intoCache.length!==2)bad.push("expected exactly TWO deletes into .next/cache (the named trim and the HOLD_ARTIFACTS-guarded hold helper), found "+intoCache.length)
for(const c of elsewhere){if(!/node_modules\/\.pnpm/.test(c[1]))bad.push("a delete outside .next/cache targets something other than the pnpm store: "+c[1].slice(0,80))}
const loopHead=(at)=>{const b=code.slice(0,at);const f=b.lastIndexOf("for (");if(f<0)return "";const e=b.indexOf("\n",f);return b.slice(f,e<0?b.length:e)}
const fnOf=(at)=>{const b=code.slice(0,at);const f=b.lastIndexOf("\nfunction ");if(f<0)return null;const m=/^function\s+(\w+)/.exec(b.slice(f+1));const end=code.indexOf("\n}\n",f);return m&&end>at?{name:m[1],body:code.slice(f,end)}:null}
const trim=intoCache.filter(c=>loopHead(c[0]).indexOf("COMPILER_CACHE_DIRS")>=0&&!fnOf(c[0]))
if(trim.length!==1)bad.push("the trim delete is not inside a top-level loop over COMPILER_CACHE_DIRS, it runs under: "+(intoCache.map(c=>loopHead(c[0])).join(" | ")||"no loop at all"))
const hold=intoCache.filter(c=>trim.indexOf(c)<0)
for(const c of hold){const fn=fnOf(c[0]);if(!fn){bad.push("a second delete into .next/cache sits outside any named function: "+c[1].slice(0,80));continue}
const guard=fn.body.indexOf("HOLD_ARTIFACTS.includes(");const thr=fn.body.indexOf("throw ");const rmAt=fn.body.indexOf("rmSync(")
if(guard<0||thr<0||!(guard<thr&&thr<rmAt))bad.push("the delete in "+fn.name+" is not behind a HOLD_ARTIFACTS check that throws first, so it can remove any cache directory")}
const lit=(name)=>{const m=new RegExp("^const\\s+"+name+"\\s*=\\s*\"([^\"]+)\"","m").exec(code.split(String.fromCharCode(39)).join("\""));return m?m[1]:null}
const A=/const\s+HOLD_ARTIFACTS\s*=\s*\[([^\]]*)\]/.exec(code)
const listOf=(m)=>m?m[1].split(",").map(x=>x.trim()).filter(Boolean).map(x=>/^[A-Z0-9_]+$/.test(x)?lit(x):x.replace(/^["\x60]|["\x60]$/g,"").split(String.fromCharCode(39)).join("")):[]
const N=/const\s+NEVER_TRIM_DIRS\s*=\s*\[([^\]]*)\]/.exec(code);const L=/const\s+COMPILER_CACHE_DIRS\s*=\s*\[([^\]]*)\]/.exec(code)
if(hold.length>0){if(!A)bad.push("a hold delete exists but no HOLD_ARTIFACTS list names what it may remove");else{const names=listOf(A);if(names.some(n=>n===null))bad.push("HOLD_ARTIFACTS names something that is not a plain string constant");for(const n of names){if(n==="fetch-cache"||n==="images"||listOf(N).indexOf(n)>=0)bad.push("HOLD_ARTIFACTS names "+n+", which must never be deleted");if(listOf(L).indexOf(n)>=0)bad.push("HOLD_ARTIFACTS names the compiler cache "+n+", so the hold can delete what only the trim may choose")}}}
const ren=[];for(let i=code.indexOf("renameSync(");i>=0;i=code.indexOf("renameSync(",i+1))if(code.slice(i-7,i)!=="import ")ren.push(i)
for(const r of ren){const fn=fnOf(r);if(!fn||fn.name!=="holdSwap")bad.push("a renameSync outside holdSwap can move a cache directory out of the upload")}
if(!L)bad.push("no COMPILER_CACHE_DIRS list, so the trim has no named set to be restricted to");else{if(L[1].indexOf("turbopack")<0)bad.push("COMPILER_CACHE_DIRS no longer names turbopack, the cache the trim exists to drop");if(L[1].indexOf("fetch-cache")>=0)bad.push("COMPILER_CACHE_DIRS names fetch-cache, so the trim can delete the incremental fetch cache again")}
if(!N)bad.push("no NEVER_TRIM_DIRS list, so nothing names the fetch cache as unremovable");else if(N[1].indexOf("fetch-cache")<0)bad.push("NEVER_TRIM_DIRS no longer names fetch-cache")
if(/for\s*\([^)]*\bof\s+cacheParts\b/.test(code))bad.push("the trim iterates cacheParts, the size-sorted list, so biggest-first is back")
const C=/^const\s+([A-Z0-9_]*(?:PACK|RATIO|CALIBRA)[A-Z0-9_]*)\s*=\s*[0-9]/m.exec(code)
if(!C)bad.push("no declared calibration constant, so the trim point is computed from raw bytes again");else{if((code.split(C[1]).length-1)<2)bad.push("the calibration constant "+C[1]+" is declared and never used");if(!new RegExp("=>[^\\n]*"+C[1]).test(code))bad.push("no conversion applies "+C[1]+" to a measurement, so the raw figure never becomes a packed one")}
if(!/const\s+TRIM_AT_PACKED_GB\s*=/.test(code))bad.push("no TRIM_AT_PACKED_GB, so the trim point is not stated in the units Vercel applies");else if((code.split("TRIM_AT_PACKED_GB").length-1)<2)bad.push("TRIM_AT_PACKED_GB is declared and never compared against anything")
if(/TRIM_AT_GIB/.test(code))bad.push("TRIM_AT_GIB is back, so a raw-GiB number is being compared with a packed ceiling")
if(bad.length){console.error(bad.join("; "));process.exit(1)}process.exit(0)'
